// CE lead webhook. Daily notify = Grok Watchdog / Grok chat. Scorpion = optional audit. Telegram = legacy. No client outreach.
// Lane: hive-os (CE surface). Operator is in building mode — register + HITL only.
const body = $json.body || $json;

const leadId = body.leadId || body.id || `lead_${Date.now()}`;
const correlationId = body.correlationId || leadId;
const source = body.source || 'client-engine';
const name = body.name || body.leadName || 'Anonymous';
const email = body.email || 'N/A';
const score = body.score || body.leadScore || 0;
const status = body.status || 'new';
const notes = body.notes || body.message || '';

const text = [
  `CE LEAD (HITL — building mode, no selling)`,
  ``,
  `Lead: ${name}`,
  `Email: ${email}`,
  `Score: ${score}`,
  `Status: ${status}`,
  `Source: ${source}`,
  notes ? `Notes: ${notes}` : '',
  ``,
  `ID: ${leadId}`,
  `Review on /pro (Tier 3). Do not send client email from n8n or Grok without HITL.`,
  `Time: ${new Date().toISOString()}`
].filter(Boolean).join('\n');

return [{
  json: {
    text,
    leadId,
    name,
    score,
    correlationId,
    registerPayload: {
      correlationId,
      jobType: 'ce.lead.received',
      goal: 'Register CE lead for HITL review — no auto-sell',
      source,
      status: 'need_hitl',
      registerTo: 'scorpion',
      summary: `CE lead ${name} ${email} status=${status}`,
      metadata: {
        lane: 'hive-os',
        leadId,
        selling: 'hold',
        telegramRequired: 'false',
        g2Ce: 'required-legacy'
      }
    }
  }
}];

const token = $env.TELEGRAM_BOT_TOKEN;
const chatId = $env.HIVE_CE_LEAD_CHAT_ID || $env.HIVE_TELEGRAM_CHAT_ID;
if (!token || token === '' || token === 'undefined' || token === 'null' || !chatId) {
  return [{
    json: {
      sent: false,
      telegramReady: false,
      leadId: $json.leadId,
      error: 'Telegram optional/legacy — skipped. Lead stays on Scorpion / Grok HITL.',
      hint: 'Do not fail G2 CE on missing Telegram. Do not send client email.'
    }
  }];
}
return [{
  json: {
    ...$json,
    telegramReady: true,
    _telegram: { token, chatId, ready: true }
  }
}];
